import{_ as r,c as a,o as t,ag as o}from"./chunks/framework.DfL_BkQ-.js";const m=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1791393402000}'),n={name:"guide/faq.md"};function i(s,e,p,l,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><p><strong>Q: What is nPlyr?</strong></p><p>A: nPlyr is a native video player for macOS and iOS/iPadOS. It plays local files and streams, includes a built-in browser that sniffs direct video links from web pages, and runs hikerView-compatible mini-programs so it can browse third-party video sources.</p><p><strong>Q: Which platforms are supported?</strong></p><p>A: macOS 14 Sonoma or later (Apple Silicon optimized, Intel supported) and iOS / iPadOS 16 or later.</p><p><strong>Q: Does it use ffmpeg or any external binary?</strong></p><p>A: No. The playback and remuxing core is built entirely on Apple&#39;s AVFoundation (AVPlayer). This keeps the app lightweight and App-Store compliant.</p><p><strong>Q: What video formats can it play?</strong></p><p>A: Whatever AVPlayer decodes natively — HLS (<code>m3u8</code>), MP4, MOV, M4V, and other containers. For HLS, nPlyr can also download and remux to MP4 in-app.</p><p><strong>Q: How is the sniffer different from a mini-program?</strong></p><p>A: The sniffer captures media links a web page actually requests. A mini-program is a rule that knows a source&#39;s structure and API, so it can navigate categories, search and parse playable links — more reliable for sites the sniffer can&#39;t crack.</p><p><strong>Q: Are mini-programs safe? Where do they come from?</strong></p><p>A: Mini-programs are community-provided hikerView-compatible rules that run inside a sandboxed JavaScript engine. They are not authored by nPlyr. See <a href="/guide/miniapp-compatibility.html">Compatibility</a> for exactly which behaviors are supported, and only install sources you trust.</p><p><strong>Q: Is my data private?</strong></p><p>A: Your library, history and bookmarks stay on your device (and sync only through your own account). The browser is a standard WKWebView with no extra trackers. There is no telemetry. See <a href="/guide/privacy.html">Privacy</a>.</p><p><strong>Q: Does the free version do everything?</strong></p><p>A: The core player, sniffer, downloads and library are fully usable. A free tier limits the number of imported mini-programs; a one-time unlock removes that limit.</p><p><strong>Q: Which languages is the UI available in?</strong></p><p>A: 25 languages, switchable live from Settings without restarting.</p><p><strong>Q: Where can I get help or join the community?</strong></p><p>A: Join the conversation on our <a href="https://discord.com/invite/XNUhXyDn3S" target="_blank" rel="noreferrer">Discord</a>. We also run Tencent channels: <a href="https://pd.qq.com/s/3t9yceyuu?b=9" target="_blank" rel="noreferrer">QQ Channel</a> is the official nPlyr channel, and <a href="https://pd.qq.com/s/bkgmqdzzf?b=9" target="_blank" rel="noreferrer">新方圆小棉袄</a> is the original Android author&#39;s channel, a great place for more sources and discussion.</p>',21)])])}const u=r(n,[["render",i]]);export{m as __pageData,u as default};
